// zcode-acp quota-dock plugin v5 (seeded by zcode-acp-server, ADR-0021)
// v2: sticky last-known quota text (a mid-turn options push without the
// quota option no longer drops the node) + order:-1 so compact width
// truncation sacrifices trailing stats sections before QUOTA.
// v5: quota-only — the per-turn TPS segment was removed (martty's own UI
// now shows throughput) and the dock renders the quota line only (GLM /
// Opencode Go / Ollama Cloud segments, whichever are configured).
return {
  inject: ["tuiSlots", "acpSessionConfig"],
  apply: (ctx) => {
    let panel
    let quotaText = null
    const readQuota = (options) => {
      const list = options || ctx.acpSessionConfig.list()
      const found = (list || []).filter((o) => o && o.id === "quota")[0]
      if (!found || typeof found.currentValue !== "string") return
      // Sticky: only an explicit empty string clears; a missing option keeps
      // the last-known text so full-replace pushes without quota cannot
      // erase the dock line.
      quotaText = found.currentValue.length > 0 ? found.currentValue : null
    }
    const nodes = () => {
      if (!quotaText) return []
      return [{ id: "zcode-acp-quota-gauge", kind: "generic", title: quotaText, body: "" }]
    }
    const render = () => { if (panel) { try { panel.update(nodes()) } catch (err) {} } }
    const stopSlot = ctx.tuiSlots.inject("conversation.composer.dock", () => {
      panel = ctx.tuiSlots.register({ name: "conversation.composer.dock", id: "zcode-acp-quota", order: -1 }, nodes())
      return () => panel.dispose()
    })
    readQuota()
    const stopSub = ctx.acpSessionConfig.subscribe((snap) => { readQuota(snap && snap.options); render() })
    return () => { stopSub && stopSub(); stopSlot && stopSlot() }
  },
}
